'use strict';
const $ = (id) => document.getElementById(id);
const state = {health:null,calibration:null,index:null,analytics:null,comparison:null,batches:{},vehicles:[],page:1,pageSize:25,split:'validation',query:'',priority:'',selected:null,payload:null,result:null,history:[],samples:[],loading:false,errors:{},analysisTab:'summary',analysisScroll:0,overviewSplit:'validation',advancedJson:'',advancedResult:null};
const esc = (v) => String(v ?? '—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (v,d=1) => Number.isFinite(Number(v)) ? Number(v).toFixed(d) : '—';
const pct = v => Number.isFinite(Number(v)) ? `${(Number(v)>1?Number(v):Number(v)*100).toFixed(1)}%` : '—';
const cls = v => `Class ${esc(v)}`;
const priorityPill = p => `<span class="pill ${p==='critical'?'bad':p==='high'?'warn':p==='medium'?'info':'good'}">${esc(p||'unknown').toUpperCase()}</span>`;
const panel = (title,sub,body,extra='') => `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<div class="sub">${sub}</div>`:''}</div>${extra}</div>${body}</section>`;
const kpi = (label,value,note,tone='blue') => `<div class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-note">${note||''}</div><div class="accent ${tone}"></div></div>`;
const empty = (msg) => `<div class="empty">${esc(msg)}</div>`;
async function api(path,opts={}){const ctl=new AbortController();const timer=setTimeout(()=>ctl.abort(),120000);let r;try{r=await fetch(path,{...opts,signal:opts.signal||ctl.signal});}catch(e){if(e.name==='AbortError')throw new Error('Request timed out. Please retry the operation.');throw e;}finally{clearTimeout(timer)}let d;try{d=await r.json()}catch{throw new Error(`Server returned non-JSON response (${r.status})`)}if(!r.ok)throw new Error(d?.error?.message||d?.detail||`Request failed (${r.status})`);return d;}
function toast(s){const t=$('toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function setPage(id){location.hash=id}
function setHeader(page,title){$('crumb').textContent=page.toUpperCase().replaceAll('-',' ');$('page-title').textContent=title;document.querySelectorAll('#nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));}
function chartTip(html,x,y){const t=$('tip');if(!t)return;t.innerHTML=html;t.hidden=false;const r=t.getBoundingClientRect();t.style.left=Math.min(innerWidth-r.width-12,Math.max(12,x+12))+'px';t.style.top=Math.min(innerHeight-r.height-12,Math.max(12,y+12))+'px'}
function hideChartTip(){if($('tip'))$('tip').hidden=true}
function chartBars(id,labels,values,color='#008f91',opts={}){const c=$(id);if(!c)return;if(!Array.isArray(values)){console.error('Chart values must be an array',id,values);values=[];}const ctx=c.getContext('2d'),w=Math.max(280,c.clientWidth),h=Math.max(190,c.clientHeight),d= devicePixelRatio||1;c.width=w*d;c.height=h*d;ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);const vs=values.map(v=>Number(v)||0),max=Math.max(1,...vs),sum=vs.reduce((a,b)=>a+b,0),L=48,R=14,T=16,B=42,pw=w-L-R,ph=h-T-B,g=pw/Math.max(1,labels.length),bw=Math.min(52,g*.62),hits=[];ctx.font='11px Segoe UI';ctx.textAlign='right';ctx.fillStyle='#718591';ctx.strokeStyle='#e4eaed';for(let i=0;i<=4;i++){let y=T+ph*i/4;ctx.beginPath();ctx.moveTo(L,y);ctx.lineTo(w-R,y);ctx.stroke();ctx.fillText(Math.round(max*(1-i/4)).toLocaleString(),L-7,y+4)}labels.forEach((lab,i)=>{let bh=vs[i]/max*ph,x=L+g*i+(g-bw)/2,y=T+ph-bh;ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,bw,bh,3);ctx.fill();ctx.textAlign='center';ctx.fillStyle='#536a76';ctx.fillText(String(lab),x+bw/2,h-14);hits.push({x,y:T,w:bw,h:ph,label:lab,value:vs[i],share:sum?vs[i]/sum:0})});c.onmousemove=e=>{let r=c.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,b=hits.find(z=>x>=z.x&&x<=z.x+z.w&&y>=z.y&&y<=z.y+z.h);if(!b){hideChartTip();return}chartTip('<b>'+esc(b.label)+'</b><br>Vehicles: '+b.value.toLocaleString()+'<br>Share: '+(b.share*100).toFixed(1)+'%',e.clientX,e.clientY)};c.onmouseleave=hideChartTip;c.tabIndex=0;c.setAttribute('aria-label','Interactive chart. Hover over a bar to inspect its value.')}
function chartDonut(id,labels,values){const c=$(id);if(!c)return;const ctx=c.getContext('2d'),w=Math.max(240,c.clientWidth),h=Math.max(190,c.clientHeight),d=devicePixelRatio||1;c.width=w*d;c.height=h*d;ctx.setTransform(d,0,0,d,0,0);ctx.clearRect(0,0,w,h);const vs=values.map(v=>Number(v)||0),total=vs.reduce((a,b)=>a+b,0)||1,cx=w/2,cy=h/2,r=Math.min(w,h)*.36,ri=r*.63,colors=['#438e69','#28618d','#e9a12b','#b92720','#008f91'];let a=-Math.PI/2,hits=[];vs.forEach((v,i)=>{let b=a+v/total*Math.PI*2;ctx.beginPath();ctx.arc(cx,cy,r,a,b);ctx.arc(cx,cy,ri,b,a,true);ctx.closePath();ctx.fillStyle=colors[i%colors.length];ctx.fill();hits.push({a,b,label:labels[i],value:v,share:v/total});a=b});ctx.textAlign='center';ctx.fillStyle='#172b3a';ctx.font='700 19px Segoe UI';ctx.fillText(total.toLocaleString(),cx,cy+3);ctx.font='11px Segoe UI';ctx.fillStyle='#718591';ctx.fillText('vehicles',cx,cy+20);c.onmousemove=e=>{let q=c.getBoundingClientRect(),dx=e.clientX-q.left-cx,dy=e.clientY-q.top-cy,dist=Math.hypot(dx,dy),a=Math.atan2(dy,dx);if(dist<ri||dist>r){hideChartTip();return}while(a< -Math.PI/2)a+=Math.PI*2;let b=hits.find(z=>a>=z.a&&a<=z.b);if(b)chartTip('<b>'+esc(b.label)+'</b><br>Vehicles: '+b.value.toLocaleString()+'<br>Share: '+(b.share*100).toFixed(1)+'%',e.clientX,e.clientY)};c.onmouseleave=hideChartTip;c.tabIndex=0;c.setAttribute('aria-label','Interactive doughnut chart. Hover to inspect category counts.')}
function countMap(obj){if(!obj||typeof obj!=='object')return {labels:[],values:[]};const entries=Object.entries(obj);return {labels:entries.map(x=>x[0]),values:entries.map(x=>Number(x[1]||0))};}
function summaryObj(d){return d?.counts||d?.priority_counts||d||{};}
async function refreshBase(){const results=await Promise.allSettled([api('/health'),api('/calibration'),api('/index/status')]);if(results[0].status==='fulfilled')state.health=results[0].value;else state.errors.health=results[0].reason.message;if(results[1].status==='fulfilled')state.calibration=results[1].value;if(results[2].status==='fulfilled')state.index=results[2].value;updateHealth();}
function updateHealth(){const ok=!!state.health?.model_loaded;$('health-dot').className='dot '+(ok?'ok':'bad');$('health-label').textContent=state.health?.status==='ok'?'Backend connected':'Backend unavailable';$('model-label').textContent=ok?'Saved model loaded':(state.health?.model_error?.message||'Model not confirmed');$('top-health').textContent=ok?'Model and API online':'Check backend / model';}
async function loadVehicles(){const q=new URLSearchParams({split:state.split,page:String(state.page),page_size:String(state.pageSize),sort:'risk'});if(state.query)q.set('q',state.query);if(state.priority)q.set('priority',state.priority);const d=await api('/vehicles?'+q);state.vehicles=d;return d;}
function overviewPage(){
  setHeader('overview','Operations overview');
  return `<div class="notice"><b>Decision-support system.</b> This platform analyses SCANIA Component X vehicle records. It does not execute maintenance actions. “Verified” means software consistency checks passed; it does not establish model correctness or physical safety.</div>
  <div class="kpi-strip" id="overview-kpis">${kpi('Backend','Checking…','FastAPI service','teal')}${kpi('Model','Checking…','Saved Random Forest','blue')}${kpi('Calibration','Checking…','Platt probability overlay','purple')}${kpi('Vehicle index','Checking…','Indexed lookup','teal')}${kpi('Validation vehicles','—','Official validation split','blue')}${kpi('Test vehicles','—','Held-out test split','blue')}</div>
  <div class="overview-toolbar"><div><span class="section-kicker">FLEET MONITORING</span><h2>Population distribution</h2><p class="sub">Switch populations to inspect the policy outputs for each dataset.</p></div><div class="segmented" role="group" aria-label="Dataset split"><button class="tab active" data-overview-split="validation">Validation</button><button class="tab" data-overview-split="test">Test</button></div></div>
  <div class="grid grid-2"><div id="priority-panel"></div><div id="decision-panel"></div></div>
  <div id="risk-hist-panel"></div>
  <div class="panel batch-panel"><div class="panel-head"><div><span class="section-kicker">WORKFLOW AUDIT</span><h2>Saved batch workflow runs</h2><div class="sub">Recorded batch execution and consistency results.</div></div><button class="btn" onclick="location.hash='verification'">Open system verification →</button></div><div id="batch-comparison"></div></div>
  <div id="recent-panel"></div>`;
}
async function hydrateOverview(){
  try{
    const [v,t,cal,bv,bt]=await Promise.all([api('/analytics/validation'),api('/analytics/test'),api('/calibration'),api('/results/batch-verification/validation').catch(()=>null),api('/results/batch-verification/test').catch(()=>null)]);
    state.overviewData={validation:v,test:t,bv,bt};
    const idx=state.index||{};
    $('overview-kpis').innerHTML=
      kpi('Backend',state.health?.status==='ok'?'Connected':'Unavailable','FastAPI service',state.health?.status==='ok'?'teal':'amber')+
      kpi('Model',state.health?.model_loaded?'Loaded':'Unavailable','Saved Random Forest',state.health?.model_loaded?'blue':'amber')+
      kpi('Calibration',cal.enabled?'Enabled':'Unavailable',cal.selected_variant||cal.reason||'Not configured',cal.enabled?'purple':'amber')+
      kpi('Vehicle index',Object.values(idx).some(x=>x?.vehicles_file)?'Available':'Check files','Indexed vehicle lookup','teal')+
      kpi('Validation vehicles',Number(v.n_vehicles||0).toLocaleString(),'Official validation split','blue')+
      kpi('Test vehicles',Number(t.n_vehicles||0).toLocaleString(),'Held-out test split','blue');
    const renderSplit=(split)=>{
      const a=state.overviewData[split]; if(!a)return;
      const priorities=a.priority_counts||{};
      const dec=Array.isArray(a.decision_counts_0_to_4)?Object.fromEntries(a.decision_counts_0_to_4.map((n,i)=>['Class '+i,n])):{};
      $('priority-panel').innerHTML=panel('Operational priority','Vehicles grouped by policy priority',`<div class="chart-box"><canvas id="priority-chart"></canvas></div><div class="legend-row">${Object.entries(priorities).map(([k,n])=>`<span><i class="legend-dot ${esc(k)}"></i>${esc(k)} <b>${Number(n).toLocaleString()}</b></span>`).join('')}</div>`);
      $('decision-panel').innerHTML=panel('Decision class chosen','Cost-sensitive policy output · counts by class',`<div class="chart-box"><canvas id="decision-chart"></canvas></div>`);
      const hist=a.calibrated_p_any_histogram||{};
      $('risk-hist-panel').innerHTML=panel('Calibrated failure probability','Number of vehicles in each calibrated probability band',`<div class="chart-box chart-tall"><canvas id="risk-hist"></canvas></div><p class="small muted">Horizontal axis: calibrated P(any failure) bands. Vertical axis: vehicle count. These are model outputs, not guaranteed real-world failure rates.</p>`);
      const p=countMap(priorities),d=countMap(dec);
      chartDonut('priority-chart',p.labels,p.values);chartBars('decision-chart',d.labels,d.values,'#008f91');chartBars('risk-hist',hist.labels||[],hist.counts||[],'#008f91');
    };
    renderSplit(state.overviewSplit||'validation');
    document.querySelectorAll('[data-overview-split]').forEach(btn=>btn.onclick=()=>{state.overviewSplit=btn.dataset.overviewSplit;document.querySelectorAll('[data-overview-split]').forEach(x=>x.classList.toggle('active',x===btn));renderSplit(state.overviewSplit)});
    const batchRows=[['Vehicles processed','vehicles_run'],['Workflows completed','vehicles_completed'],['Verified','verified'],['Needs review','needs_review'],['Workflow errors','workflow_errors'],['Failed checks','failed_checks'],['Dashboard / workflow disagreements','dashboard_workflow_disagreements'],['Mean workflow time','mean_workflow_ms_per_vehicle'],['Total batch time','total_seconds']];
    const val=(b,key)=>{if(!b)return '—';if(key==='verified'||key==='needs_review')return b.final_status_counts?.[key]??'—';if(key==='workflow_errors')return Array.isArray(b.workflow_errors)?b.workflow_errors.length:Object.keys(b.workflow_errors||{}).length;if(key==='failed_checks')return Object.values(b.failed_check_counts||{}).reduce((x,y)=>x+Number(y||0),0);if(key==='mean_workflow_ms_per_vehicle')return b[key]!==undefined?num(b[key],2)+' ms':'—';if(key==='total_seconds')return b[key]!==undefined?num(b[key],2)+' s':'—';return b[key]??'—'};
    $('batch-comparison').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Measure</th><th>Validation batch</th><th>Test batch</th></tr></thead><tbody>${batchRows.map(([label,key])=>`<tr><th>${label}</th><td>${val(bv,key)}</td><td>${val(bt,key)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Batch summaries reflect the saved runs included with this project. “Verified” is a software workflow status only.</p>`;
    $('recent-panel').innerHTML=panel('Recent analysis activity','Browser-session history only. The server does not persist individual analysis history.',state.history.length?`<div class="table-wrap"><table><thead><tr><th>Time</th><th>Vehicle</th><th>Workflow</th><th>Outcome</th></tr></thead><tbody>${state.history.slice(0,8).map(x=>`<tr><td>${esc(x.at)}</td><td><b>${esc(x.id)}</b></td><td>${esc(x.workflow)}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('No analyses in this browser session yet. Run a vehicle workflow to see it here.'));
  }catch(e){$('view').insertAdjacentHTML('beforeend',`<div class="error">Overview data could not be loaded: ${esc(e.message)}</div>`)}
}
function renderBatch(id,title,b){if(!b){$(id).innerHTML=panel(title,'Batch summary unavailable',empty('Run scripts/run_batch_workflow.py to create the batch summary.'));return;}const n=b.vehicles_run??b.total_vehicles??'—',completed=b.vehicles_completed??'—',dis=b.dashboard_workflow_disagreements??'—',err=Object.keys(b.workflow_errors||{}).length;$(id).innerHTML=panel(title,'Batch execution and consistency checks',`<div class="grid grid-3">${kpi('Vehicles run',n,'Batch size')}${kpi('Completed',completed,'Workflow completed','teal')}${kpi('Disagreements',dis,'Dashboard vs live workflow',dis===0?'teal':'amber')}</div><p class="small muted">Final statuses: ${esc(JSON.stringify(b.final_status_counts||{}))} · Workflow errors: ${err} · Replans: ${esc(JSON.stringify(b.replan_count_distribution||{}))}</p>`);}
function analysisPage(){setHeader('analysis','Vehicle analysis');return `<div class="notice">Select a vehicle from the indexed validation/test population, load its 113 model inputs, then run all four deterministic agents. Ground-truth labels are never included in the agent input.</div><div class="panel"><div class="toolbar"><div class="field"><label>DATA SPLIT</label><select id="split-select"><option value="validation">Validation</option><option value="test">Test</option></select></div><div class="field search"><label>SEARCH VEHICLE ID</label><input id="vehicle-search" placeholder="Enter vehicle ID or prefix"></div><div class="field"><label>PRIORITY FILTER</label><select id="priority-select"><option value="">All priorities</option><option>low</option><option>medium</option><option>high</option><option>critical</option></select></div><button class="btn" id="search-vehicles">Search</button></div><div id="vehicle-table">Loading indexed vehicles…</div><div class="row" style="justify-content:space-between;margin-top:12px"><span id="vehicle-page-label" class="small muted"></span><div class="row"><button class="btn" id="prev-page">Previous</button><button class="btn" id="next-page">Next</button></div></div></div><div class="two-col"><div id="vehicle-input-panel">${empty('Choose a vehicle to inspect its input features.')}</div><div id="analysis-output-panel">${empty('Run the workflow to see prediction, investigation, decision and verification reports.')}</div></div>`}
async function hydrateAnalysis(){const split=$('split-select'),search=$('vehicle-search'),pri=$('priority-select');split.value=state.split;search.value=state.query;pri.value=state.priority;const load=async()=>{const nextSplit=split.value;if(nextSplit!==state.split){state.selected=null;state.result=null;state.analysisTab='summary';$('vehicle-input-panel').innerHTML=empty('Choose a vehicle to inspect its input features.');$('analysis-output-panel').innerHTML=empty('Run the workflow after selecting a vehicle.')}state.split=nextSplit;state.query=search.value.trim();state.priority=pri.value;state.page=1;await drawVehicleList()};$('search-vehicles').onclick=load;split.onchange=load;pri.onchange=load;search.onkeydown=e=>{if(e.key==='Enter')load()};$('prev-page').onclick=async()=>{if(state.page>1){state.page--;await drawVehicleList()}};$('next-page').onclick=async()=>{if(state.vehicles?.has_next||state.page*state.pageSize<(state.vehicles?.total||0)){state.page++;await drawVehicleList()}};await drawVehicleList();if(state.selected){renderSelectedVehicle();if(state.result)renderAnalysisResult(state.result);window.scrollTo(0,state.analysisScroll||0)}}
async function drawVehicleList(){try{const d=await loadVehicles();const items=d.vehicles||d.items||[];$('vehicle-table').innerHTML=items.length?`<div class="table-wrap"><table><thead><tr><th>Vehicle ID</th><th>Decision class</th><th>Priority</th><th>Calibrated P(failure)</th><th>Risk percentile</th></tr></thead><tbody>${items.map(x=>`<tr class="clickable ${state.selected?.vehicle_id===x.vehicle_id?'selected-row':''}" data-id="${esc(x.vehicle_id)}"><td><b>${esc(x.vehicle_id)}</b></td><td>${cls(x.decision_class??x.predicted_class)}</td><td>${priorityPill(x.priority)}</td><td>${pct(x.calibrated_p_any_failure??x.calibrated_probability_any_failure??x.p_any_failure_calibrated??x.probability_any_failure)}</td><td>${pct(x.risk_percentile)}</td></tr>`).join('')}</tbody></table></div>`:empty('No vehicles match this query.');$('vehicle-page-label').textContent=`Page ${state.page} · ${Number(d.total||0).toLocaleString()} vehicles`;document.querySelectorAll('#vehicle-table tr[data-id]').forEach(tr=>tr.onclick=()=>selectVehicle(tr.dataset.id));}catch(e){$('vehicle-table').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function selectVehicle(id){try{const d=await api(`/vehicles/${state.split}/${encodeURIComponent(id)}`);state.selected=d;state.result=null;state.analysisTab='summary';renderSelectedVehicle();$('analysis-output-panel').innerHTML=empty('Vehicle loaded. Run the workflow to generate an evidence-backed report.');document.querySelectorAll('#vehicle-table tr[data-id]').forEach(tr=>tr.classList.toggle('selected-row',tr.dataset.id===String(id)))}catch(e){toast(e.message)}}
function renderSelectedVehicle(){if(!state.selected||!$('vehicle-input-panel'))return;const d=state.selected,entries=Object.entries(d.features||{});$('vehicle-input-panel').innerHTML=panel(`Vehicle ${esc(d.vehicle_id)}`,'Indexed sensor and specification inputs',`<div class="row" style="justify-content:space-between"><span class="pill info">${entries.length} model features</span><button class="btn primary" id="run-selected">Run four-agent workflow</button></div><div class="field" style="margin-top:12px"><label>SEARCH FEATURES</label><input id="feature-search" placeholder="Find a feature by name…"></div><div class="feature-grid" id="feature-grid" style="margin-top:13px">${entries.map(([k,v])=>`<div class="feature" data-feature="${esc(k.toLowerCase())}"><small>${esc(k)}</small><b>${v===null?'Missing':esc(typeof v==='number'?num(v,3):v)}</b></div>`).join('')}</div>`);$('run-selected').onclick=()=>runSelected();$('feature-search').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#feature-grid .feature').forEach(el=>el.hidden=!el.dataset.feature.includes(q))}}
async function runSelected(){if(!state.selected)return;const id=state.selected.vehicle_id;$('analysis-output-panel').innerHTML='<div class="loading">Running prediction → investigation → decision → verification…</div>';try{const r=await api(`/analysis/${state.split}/${encodeURIComponent(id)}`,{method:'POST'});state.result=r;state.history.unshift({at:new Date().toLocaleTimeString(),id,workflow:'Four-agent workflow',status:r.final_status||r.status});renderAnalysisResult(r);toast('Workflow completed');}catch(e){$('analysis-output-panel').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
function reportBlock(r){if(!r)return '';const list=(a)=>Array.isArray(a)&&a.length?`<ul>${a.map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ul>`:'<p class="small muted">No items reported.</p>';return `<h4>What it received</h4>${list(r.received)}<h4>What it performed</h4>${list(r.performed)}<h4>Findings</h4>${(r.findings||[]).map(f=>`<div class="finding ${esc(f.importance)}"><b>${esc(f.title)}</b><div>${esc(f.detail)}</div></div>`).join('')||'<p class="small muted">No findings.</p>'}<h4>Passed to next stage</h4>${list(r.passed_on)}<h4>Limitations</h4>${list(r.limitations)}`;}
function renderAnalysisResult(r){const p=r.prediction||{},d=r.recommendation||{},v=r.verification||{};const tab=state.analysisTab||'summary';$('analysis-output-panel').innerHTML=panel('Workflow result',`Vehicle ${esc(state.selected?.vehicle_id)} · ${esc(r.final_status||r.status)}`,`<div class="grid grid-2">${kpi('Decision class',d.recommended_class??'—','Minimum expected-cost action','blue')}${kpi('Priority',String(d.priority||'—').toUpperCase(),d.priority_rationale||'','amber')}${kpi('P(any failure)',pct(p.calibrated_probability_any_failure??p.probability_any_failure),'Calibrated where enabled','teal')}${kpi('Verification',esc(v.status||'—'),`${(v.checks||[]).filter(x=>x.passed).length}/${(v.checks||[]).length} checks passed`,'purple')}</div><div class="warning" style="margin-top:12px">${esc(d.safety_notice||'Decision support only. Human review required; no maintenance action is executed.')}</div>${r.evaluation_only?.recorded_class_label!==null&&r.evaluation_only?.recorded_class_label!==undefined?`<div class="notice"><b>Evaluation-only reference (not agent input):</b> recorded class ${esc(r.evaluation_only.recorded_class_label)}. This label was retrieved after the workflow for comparison only.</div>`:''}<div class="tabs"><button class="tab ${tab==='summary'?'active':''}" data-tab="summary">Summary</button><button class="tab ${tab==='agents'?'active':''}" data-tab="agents">Agent reports</button><button class="tab ${tab==='checks'?'active':''}" data-tab="checks">Verification checks</button></div><div id="result-tab-content">${resultTab(tab,r)}</div>`);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.analysisTab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));$('result-tab-content').innerHTML=resultTab(b.dataset.tab,r)});}
function resultTab(tab,r){const p=r.prediction||{},i=r.investigation||{},d=r.recommendation||{},v=r.verification||{};if(tab==='agents')return `<div class="agent-grid">${[['Prediction Agent',p.report],['Investigation Agent',i.report],['Decision Agent',d.report],['Verification Agent',v.report]].map(([n,x])=>`<article class="agent-card"><div class="agent-title"><h3>${n}</h3><span class="pill info">Deterministic Python</span></div>${reportBlock(x)}</article>`).join('')}</div>`;if(tab==='checks')return (v.checks||[]).map(c=>`<div class="check"><span class="check-icon ${c.passed?'':'fail'}">${c.passed?'✓':'!'}</span><div><b>${esc(c.name||c.id)}</b><p>${esc(c.what_checked||c.message)}</p><p><b>Why it matters:</b> ${esc(c.why_it_matters||'')}</p></div><span class="pill ${c.passed?'good':'bad'}">${c.passed?'PASS':'FAIL'}</span></div>`).join('')||empty('No verification checks returned.');const costs=d.expected_costs||{};const min=Math.min(...Object.values(costs).map(Number).filter(Number.isFinite));return `<div class="split"><div><h4>Model class scores</h4><p class="small muted">Raw model scores are not calibrated real-world probabilities. The decision agent uses the calibrated distribution when calibration is enabled.</p>${Object.entries(p.decision_probabilities||p.probabilities||{}).map(([k,val])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Math.min(100,Number(val)*100))}%"></div></div><b>${pct(val)}</b></div>`).join('')}<h4>Investigation summary</h4><p class="small">${esc(i.summary||'No investigation summary.')}</p><h4>Evidence</h4>${(i.evidence||[]).map(e=>`<div class="finding"><b>${esc(e.id)} · ${esc(e.kind)}</b><div>${esc(e.statement)} ${e.value!==null&&e.value!==undefined?`<b>${esc(e.value)}</b>`:''}</div></div>`).join('')||empty('No evidence items.')}</div><div><h4>Expected maintenance cost by decision</h4><p class="small muted">Project-defined cost units, not currency. Lower is preferred.</p>${Object.entries(costs).map(([k,val])=>`<div class="cost-row ${Number(val)===min?'selected':''}"><b>${k===String(d.recommended_class)?'✓ ':''}${esc(k)}</b><div class="bar-track"><div class="bar-fill ${Number(val)===min?'teal':''}" style="width:${min===0?0:Math.max(1,Number(val)/(Math.max(...Object.values(costs).map(Number))||1)*100)}%"></div></div><b>${num(val,3)}</b></div>`).join('')}<h4>Decision explanation</h4><p class="small">${esc(d.explanation||'')}</p><h4>Verification assurance</h4><pre class="small" style="white-space:pre-wrap">${esc(JSON.stringify(v.assurance||{},null,2))}</pre></div></div>`;}
function agentsPage(){
  setHeader('agents','Agent operations');
  const r=state.result;
  const defs=[
    ['Prediction Agent','Transforms the 113 validated model inputs into raw class scores, calibrated probabilities and risk indicators.'],
    ['Investigation Agent','Checks input completeness, population risk context, unusual readings and uncertainty limitations.'],
    ['Decision Agent','Calculates expected costs for all five possible decisions and proposes engineer-reviewed actions.'],
    ['Verification Agent','Independently checks arithmetic, calibration and policy consistency, then reports software assurance.']
  ];
  const reports=[r?.prediction?.report,r?.investigation?.report,r?.recommendation?.report,r?.verification?.report];
  const names=['Prediction','Investigation','Decision','Verification'];
  const pipeline=`<div class="agent-pipeline">${defs.map((x,i)=>`<div class="pipeline-stage ${r?'stage-done':''}"><span class="stage-number">0${i+1}</span><b>${x[0]}</b><small>${r?'Report returned':'Deterministic Python stage'}</small></div>`).join('')}</div>`;
  const details=defs.map((x,i)=>`<details class="agent-report" ${i===0?'open':''}><summary><span class="stage-number">0${i+1}</span><span><b>${x[0]}</b><small>${x[1]}</small></span><span class="pill ${r?'good':'info'}">${r?'Completed':'Awaiting run'}</span></summary><div class="agent-report-body">${r?reportBlock(reports[i]):`<p class="small muted">Run a vehicle workflow to view the actual received inputs, processing steps, findings, handoff and limitations for this agent.</p>`}</div></details>`).join('');
  return `<div class="notice"><b>Execution model:</b> these are four deterministic Python agents, not conversational LLM agents. Each stage receives structured outputs from the previous stage. The reports below are populated only from the latest real workflow response.</div>${r?`<div class="latest-strip"><span>Latest workflow</span><b>${esc(state.selected?.vehicle_id??r.vehicle_id??'Vehicle')}</b><span>${esc(r.final_status||r.status||'Completed')}</span><time>${esc(state.history[0]?.at||'Current session')}</time></div>`:''}${panel('Agent execution sequence','Prediction → Investigation → Decision → Verification',pipeline)}<section class="panel"><div class="panel-head"><div><h2>Agent reports</h2><div class="sub">Expand each stage to inspect the exact report returned by the backend.</div></div>${r?'<span class="pill good">4 reports available</span>':'<span class="pill info">No workflow loaded</span>'}</div>${details}</section>`;
}
function decisionsPage(){
  setHeader('decisions','Maintenance decisions');
  const r=state.result,d=r?.recommendation,p=r?.prediction,v=r?.verification;
  if(!d)return `<div class="notice">Maintenance decisions are generated by the Decision Agent after prediction and investigation. Select a vehicle in Vehicle Analysis and run the complete workflow to populate this page.</div>${panel('Decision workspace','No completed vehicle analysis is available in this browser session.',`<div class="empty-state"><b>No decision to display</b><p>Choose a vehicle, inspect its 113 model inputs, then run all four deterministic agents.</p><button class="btn primary" onclick="location.hash='analysis'">Open vehicle analysis</button></div>`)}`;
  const costs=d.expected_costs||{}, entries=Object.entries(costs).sort((a,b)=>Number(a[0])-Number(b[0]));
  const numeric=entries.map(([k,x])=>[Number(k),Number(x)]).filter(x=>Number.isFinite(x[1]));
  const max=Math.max(1,...numeric.map(x=>x[1]));
  const chosen=Number(d.recommended_class), raw=Number(d.raw_argmax_class), runner=Number(d.runner_up_class);
  const chosenCost=Number(costs[String(chosen)]), runnerCost=Number(costs[String(runner)]);
  const gap=Number.isFinite(Number(d.margin_to_runner_up))?Number(d.margin_to_runner_up):(runnerCost-chosenCost);
  const gapPct=runnerCost>0?gap/runnerCost*100:null;
  const actions=(d.actions||[]).map(a=>`<div class="action-card"><div class="action-top"><b>${esc(String(a.type||'Engineering review').replaceAll('_',' '))}</b><span class="pill warn">${esc(a.urgency||'Review')}</span></div><p>${esc(a.description||'No action description returned.')}</p><small>${a.executed?'Executed':'Not executed'} · ${a.requires_human_approval?'Requires human approval':'Approval requirement not specified'}</small></div>`).join('')||`<p class="muted small">No proposed actions were returned by the Decision Agent.</p>`;
  const costRows=numeric.map(([key,value])=>`<div class="decision-cost-row ${key===chosen?'is-chosen':''} ${key===runner?'is-runner':''}"><div class="cost-label">Class ${key}${key===chosen?'<span class="cost-tag chosen-tag">Lowest cost</span>':''}${key===runner?'<span class="cost-tag runner-tag">Runner-up</span>':''}${key===raw?'<span class="cost-tag raw-tag">Raw argmax</span>':''}</div><div class="cost-track"><span style="width:${Math.max(0,Math.min(100,value/max*100))}%"></span></div><b class="cost-value">${num(value,2)}</b></div>`).join('');
  const probs=p?.decision_probabilities||p?.probabilities||{};
  const rawScores=p?.raw_probabilities||p?.raw_class_probabilities||{};
  const calScores=p?.calibrated_probabilities||p?.calibrated_class_probabilities||{};
  const costBreakdown=d.cost_breakdown||{};
  const breakdown=costBreakdown[String(chosen)]||{};
  const evaluation=r.evaluation_only||{};
  const assurance=v?.assurance||{};
  const checks=v?.checks||[];
  const explainDiff=chosen!==raw?`The cost-sensitive policy selected Class ${chosen}, while the raw model argmax is Class ${raw}. The two answer different questions: the model argmax selects the largest raw score; the policy selects the decision with the lowest expected project cost.`:`The cost-sensitive decision matches the raw model argmax (Class ${chosen}) for this vehicle.`;
  const timestamp=state.history[0]?.at||'Current session';
  return `<div class="latest-strip"><span>Latest analysis</span><b>${esc(state.selected?.vehicle_id??r.vehicle_id??'Selected vehicle')}</b><span>Decision ${cls(chosen)}</span>${priorityPill(d.priority)}<span class="latest-status">${esc(v?.status||r.final_status||'Completed')}</span><time>${esc(timestamp)}</time></div>
  <p class="decision-intro">Decision for vehicle <b>${esc(state.selected?.vehicle_id??r.vehicle_id??'—')}</b>. Expected costs are project-defined units from the cost matrix. They are not currency.</p>
  <section class="decision-hero"><div class="hero-main"><span class="hero-label">Recommended decision</span><strong>${cls(chosen)}</strong><p>${esc(explainDiff)}</p></div><div class="hero-stat"><span>Raw argmax</span><b>${cls(raw)}</b></div><div class="hero-stat"><span>Runner-up</span><b>${Number.isFinite(runner)?cls(runner):'—'}</b></div><div class="hero-stat"><span>Cost gap to runner-up</span><b>${Number.isFinite(gap)?num(gap,2)+' <small>units</small>':'—'}</b></div><div class="hero-stat"><span>Priority</span>${priorityPill(d.priority)}</div><div class="hero-stat"><span>Human approval</span><b>Required</b></div></section>
  <div class="decision-layout"><section class="panel decision-cost-panel"><div class="panel-head"><div><h2>Expected cost of each possible decision</h2><div class="sub">Project cost units, lower is better. Bars start at zero.</div></div></div><div class="decision-cost-list">${costRows}</div><p class="small muted">The runner-up is the second-lowest expected cost from the returned decision costs. All five values are shown directly from the Decision Agent response.</p>
  <details class="explain-details"><summary>Worked example for the selected decision</summary><p class="small">Expected cost for decision Class ${chosen} is the sum of the probability of each actual class multiplied by the cost of choosing Class ${chosen} for that actual class.</p>${Object.entries(breakdown).length?`<div class="table-wrap"><table><thead><tr><th>Actual class</th><th>Probability-weighted cost</th></tr></thead><tbody>${Object.entries(breakdown).map(([k,x])=>`<tr><td>Class ${esc(k)}</td><td>${num(x,4)}</td></tr>`).join('')}</tbody></table></div>`:`<p class="muted small">The backend did not return the per-class cost breakdown for this run.</p>`}<b>Reported expected cost: ${num(chosenCost,4)} project units.</b></details>
  <details class="explain-details"><summary>Cost matrix used by the project</summary><p class="small">The backend response includes the cost-matrix orientation: <b>${esc(d.cost_matrix_orientation||'not returned')}</b>. The exact matrix is defined in the backend project configuration and is not duplicated or reconstructed in this frontend.</p></details></section>
  <section class="panel reading-panel"><h2>Reading the result</h2><div class="reading-step"><h3>1. What the model predicted</h3><p>The raw model argmax is <b>${cls(raw)}</b>. This identifies the largest raw model score; raw scores should not be interpreted as real-world probabilities.</p></div><div class="reading-step"><h3>2. What the cost-sensitive policy selected</h3><p>The policy selected <b>${cls(chosen)}</b>${Number.isFinite(chosenCost)?`, with an expected cost of <b>${num(chosenCost,2)} units</b>`:''}. It selects the minimum expected cost among the five decisions.</p></div><div class="reading-step"><h3>3. Why it selected that decision</h3><ul><li>${esc(d.explanation||'The Decision Agent selected the class with the lowest expected cost.')}</li><li>${esc(d.priority_rationale||'Priority is based on the configured operational risk rules.')}</li><li>Missed failures carry higher project-defined costs than false alarms; the cost matrix is asymmetric.</li></ul><p class="small muted">${esc(d.uncertainty_statement||'Decision uncertainty should be reviewed alongside the prediction and investigation evidence.')}</p></div><div class="reading-step"><h3>4. How close the runner-up was</h3><p>${Number.isFinite(runner)&&Number.isFinite(gap)?`Class ${runner} was next at ${num(runnerCost,2)} units, ${num(gap,2)} units above the selected decision${gapPct!==null?` (${num(gapPct,1)}% of the runner-up cost)`:''}.`:'Runner-up cost details were not returned.'} A smaller gap indicates a more sensitive choice.</p></div><div class="reading-step"><h3>5. What the engineer should review</h3>${actions}<h4>Limitations stated by the agent</h4><ul>${(d.report?.limitations||[]).map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Advisory only. Requires qualified human review.</li>'}</ul></div></section></div>
  <div class="warning decision-warning"><b>Recommendation only.</b> ${esc(d.safety_notice||'This recommendation is advisory. It needs review and approval by a qualified maintenance engineer. No maintenance action is executed automatically.')}</div>
  <details class="evaluation-details"><summary><b>Evaluation-only reference</b><span>not used by any agent</span></summary><div class="evaluation-body">${evaluation.recorded_class_label!==null&&evaluation.recorded_class_label!==undefined?`<p>Recorded dataset class label: <b>${cls(evaluation.recorded_class_label)}</b></p>`:'<p>No recorded class label was returned for this vehicle.</p>'}<p class="small muted">${esc(evaluation.note||'This reference is fetched after the workflow and is never passed to prediction, investigation, or decision agents.')}</p></div></details>`;
}
function analyticsPage(){setHeader('analytics','Model analytics');return `<div class="notice">Use the held-out test split for the unbiased evaluation view. Validation metrics are not an independent test because calibration was fitted using validation data.</div><div class="toolbar"><div class="field"><label>DATA SPLIT</label><select id="analytics-split"><option value="test">Held-out test</option><option value="validation">Validation (calibration set)</option></select></div><button class="btn" id="load-analytics">Load analytics</button></div><div id="analytics-content"><div class="loading">Loading analytics…</div></div><div id="comparison-content"></div>`;}
async function hydrateAnalytics(){const load=async()=>{const split=$('analytics-split').value;state.analyticsSplit=split;$('analytics-content').innerHTML='<div class="loading">Loading measured model evaluation…</div>';try{const [a,c]=await Promise.all([api('/model/evaluate?split='+split),api('/results/model-comparison')]);state.analytics=a;state.comparison=c;renderAnalytics(a,c,split)}catch(e){$('analytics-content').innerHTML=`<div class="error">${esc(e.message)}</div><p class="small muted">Evaluation requires the labelled split files and saved model to be available on the backend.</p>`}};$('load-analytics').onclick=load;await load()}
function confusionHTML(cm){if(!Array.isArray(cm)||!cm.length)return empty('Confusion matrix unavailable from evaluation response.');const max=Math.max(1,...cm.flat().map(Number));return `<div class="table-wrap"><table class="confusion-table"><thead><tr><th>Actual / Predicted</th>${[0,1,2,3,4].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${cm.map((row,i)=>`<tr><th>Class ${i}</th>${row.map(v=>`<td style="background:rgba(0,143,145,${Math.min(.58,.05+Number(v)/max*.53)})">${Number(v).toLocaleString()}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small muted">Rows are actual classes; columns are predicted classes.</p>`}
function perClassHTML(per){if(!per)return empty('Per-class metrics unavailable.');return `<div class="table-wrap"><table><thead><tr><th>Class</th><th>Precision</th><th>Recall</th><th>F1</th><th>Support</th></tr></thead><tbody>${[0,1,2,3,4].map(i=>{let x=per[String(i)]||{};return `<tr><td>Class ${i}</td><td>${pct(x.precision)}</td><td>${pct(x.recall)}</td><td>${num(x.f1,3)}</td><td>${num(x.support,0)}</td></tr>`}).join('')}</tbody></table></div>`}
function renderAnalytics(a,c,split){
  const live=a.expected_cost||a.policies?.expected_cost||{},raw=a.raw_argmax||a.policies?.raw_argmax||{},cm=live.confusion_matrix,per=live.per_class,actual=a.actual_class_counts||{},pred=a.raw_argmax_prediction_counts||{},rows=(c?.rows||[]).filter(x=>x.split===split),m2=c?.extra?.m2_test_detail;
  const comp=rows.length?`<div class="table-wrap"><table><thead><tr><th>Policy</th><th>Mean cost</th><th>Balanced accuracy</th><th>Macro F1</th><th>Evaluation basis</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.label||x.key)}</b></td><td>${num(x.mean_cost,4)}</td><td>${x.balanced_accuracy==null?'—':pct(x.balanced_accuracy)}</td><td>${x.macro_f1==null?'—':num(x.macro_f1,4)}</td><td>${esc(x.basis||'')}</td></tr>`).join('')}</tbody></table></div>`:empty('No comparison rows returned for this split.');
  const m2Panel=(split==='test'&&m2)?`<div class="notice"><b>Saved M2 held-out experiment (separate from live M0 evaluation)</b><br>${esc(m2.evaluation_basis||'')}</div><div class="grid grid-4">${kpi('M2 mean cost',num(m2.mean_cost,4),'Project-defined units','teal')}${kpi('Balanced accuracy',pct(m2.balanced_accuracy),'M2 cost-sensitive policy','blue')}${kpi('Macro F1',num(m2.macro_f1,4),'M2 cost-sensitive policy','purple')}${kpi('Cost reduction vs M0',num(m2.cost_reduction_vs_m0_percent,2)+'%','Saved held-out experiment','teal')}</div><div class="grid grid-2" style="margin-top:14px">${panel('M2 confusion matrix','Saved held-out test experiment · rows actual, columns predicted',confusionHTML(m2.confusion_matrix_rows_actual_cols_predicted))}${panel('M2 per-class performance','Precision, recall, F1 and support from saved confusion matrix',perClassHTML(m2.per_class))}</div><div class="small muted">M2 predicted counts (classes 0–4): ${m2.prediction_counts_0_to_4.map((v,i)=>`Class ${i}: ${Number(v).toLocaleString()}`).join(' · ')}. Actual counts: ${m2.actual_class_counts_0_to_4.map((v,i)=>`Class ${i}: ${Number(v).toLocaleString()}`).join(' · ')}.</div>`:'';
  $('analytics-content').innerHTML=`<div class="notice"><b>Live evaluation of the currently loaded model artifact</b><br>${esc(a.evaluation_label||split+' evaluation')}<br>${esc(a.protocol||'')}<br><b>Policy:</b> expected-cost decision on the loaded artifact's output. This live evaluation is not the saved M2 calibrated experiment.</div><div class="grid grid-4">${kpi('Vehicles evaluated',num(a.n_vehicles,0),'Labelled records','blue')}${kpi('Balanced accuracy',pct(live.balanced_accuracy),'Live expected-cost policy','teal')}${kpi('Macro F1',num(live.macro_f1,4),'Live expected-cost policy','purple')}${kpi('Mean cost',num(live.mean_cost,4),'Project-defined units · live policy','amber')}</div>${a.warning?`<div class="warning">${esc(a.warning)}</div>`:''}<div class="grid grid-2" style="margin-top:14px">${panel('Live confusion matrix (M0)','Currently loaded model · original expected-cost rule',confusionHTML(cm))}${panel('Live per-class performance (M0)','Precision, recall, F1 and support',perClassHTML(per))}</div><div class="grid grid-2" style="margin-top:14px">${panel('Actual class distribution','Ground truth used only for offline scoring',`<div class="chart-box"><canvas id="actual-class-chart"></canvas></div>`)}${panel('Raw model prediction distribution','Highest raw class score, before cost-sensitive action',`<div class="chart-box"><canvas id="pred-class-chart"></canvas></div>`)}</div>${m2Panel}${panel('Policy comparison','Saved, measured experiment results (not the live evaluation above)',comp)}<div class="warning" style="margin-top:14px"><b>Interpretation and limitations</b><ul><li>The SCANIA labels are highly imbalanced; report per-class support and recall alongside aggregate metrics.</li><li>M2 held-out results are a separately saved experiment with calibration fitted on validation and test scored once.</li><li>Classes 1 and 2 have zero recall in the saved M2 test result; class-specific detection remains a major limitation.</li><li>Lower expected cost does not necessarily mean higher classification accuracy; the project cost matrix weights errors differently.</li><li>Validation is used for calibration/selection. The held-out test split is the independent final evaluation population.</li><li>Raw model outputs are not calibrated real-world failure probabilities.</li><li>Software verification does not establish model correctness or physical equipment safety.</li></ul></div><details class="panel raw-details"><summary>Technical live-evaluation response (raw JSON)</summary><pre class="json-view">${esc(JSON.stringify(a,null,2))}</pre></details>`;
  chartBars('actual-class-chart',[0,1,2,3,4].map(x=>'Class '+x),[0,1,2,3,4].map(x=>Number(actual[String(x)]||0)),'#28618d');chartBars('pred-class-chart',[0,1,2,3,4].map(x=>'Class '+x),Array.isArray(pred)?pred:[0,1,2,3,4].map(x=>Number(pred[String(x)]??pred[x]??0)),'#008f91');
  $('comparison-content').innerHTML=panel('Model comparison notes','Experiment selection and evidence',Array.isArray(c?.honest_summary)?`<ul>${c.honest_summary.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:c?.honest_summary?esc(c.honest_summary):empty('No comparison notes returned.'));
}
function verificationPage(){setHeader('verification','System verification');return `<div class="notice">Software verification checks internal consistency only. It does not establish that a prediction is correct or that a vehicle is physically safe.</div><div class="toolbar"><div class="field"><label>DATA SPLIT</label><select id="verify-split"><option value="validation">Validation</option><option value="test">Test</option></select></div><button class="btn" id="load-verification">Load batch verification</button></div><div id="verify-content">${empty('Load a saved batch verification summary.')}</div>${state.result?panel('Latest vehicle-level verification','Most recent workflow result',resultTab('checks',state.result)):''}`;}
function verificationSummary(d){
  const countMap=(obj)=>Object.entries(obj||{}).map(([k,v])=>`${esc(k.replaceAll('_',' '))}: ${esc(v)}`).join(' · ')||'None';
  const errors=Array.isArray(d.workflow_errors)?d.workflow_errors.length:Object.keys(d.workflow_errors||{}).length;
  const failed=Object.values(d.failed_check_counts||{}).reduce((a,b)=>a+Number(b||0),0);
  const statuses=d.final_status_counts||{};
  return `<div class="grid grid-4">
    ${kpi('Vehicles processed',num(d.vehicles_run,0),'Selected split','blue')}
    ${kpi('Workflows completed',num(d.vehicles_completed,0),'Completed executions','teal')}
    ${kpi('Verified',num(statuses.verified,0),'Software checks passed','purple')}
    ${kpi('Needs review',num(statuses.needs_review,0),'Human review recommended','amber')}
  </div>
  <div class="grid grid-3" style="margin-top:14px">
    ${kpi('Workflow errors',errors,'Execution errors',errors?'amber':'teal')}
    ${kpi('Failed checks',failed,'Aggregated failed-check count',failed?'amber':'teal')}
    ${kpi('Disagreements',num(d.dashboard_workflow_disagreements,0),'Dashboard/workflow differences','blue')}
  </div>
  <div class="grid grid-2" style="margin-top:14px">
    ${panel('Priority distribution','Vehicles in this batch',`<div class="bar-list">${Object.entries(d.priority_counts||{}).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar-track"><div class="bar-fill ${k==='critical'?'red':k==='high'?'amber':''}" style="width:${Math.max(0,Math.min(100,Number(v)/(Number(d.vehicles_run)||1)*100))}%"></div></div><b>${num(v,0)}</b></div>`).join('')||empty('No priority counts returned.')}</div>`)}
    ${panel('Failed checks','Aggregated by check name',`<div class="bar-list">${Object.entries(d.failed_check_counts||{}).map(([k,v])=>`<div class="bar-row"><span>${esc(k)}</span><div class="bar-track"><div class="bar-fill red" style="width:${Math.max(0,Math.min(100,Number(v)/(Number(d.vehicles_run)||1)*100))}%"></div></div><b>${num(v,0)}</b></div>`).join('')||empty('No failed checks reported.')}</div>`)}
  </div>
  <div class="notice" style="margin-top:14px"><b>What this result means:</b> ${esc(d.meaning||'Workflow verification summarizes software consistency checks only. It does not establish model correctness or physical equipment safety.')}</div>
  <div class="small muted">Split: ${esc(d.split)} · Average workflow time: ${num(d.mean_workflow_ms_per_vehicle,2)} ms/vehicle · Total batch time: ${num(d.total_seconds,1)} s · Sampling: ${esc(d.sampling?.method||'not specified')}</div>
  <details class="panel raw-details"><summary>Technical details (raw batch response)</summary><pre class="json-view">${esc(JSON.stringify(d,null,2))}</pre></details>`;
}
async function hydrateVerification(){
  const load=async()=>{
    $('verify-content').innerHTML='<div class="loading">Loading saved batch verification…</div>';
    try{
      const d=await api('/results/batch-verification/'+$('verify-split').value);
      $('verify-content').innerHTML=verificationSummary(d);
    }catch(e){$('verify-content').innerHTML=`<div class="error">${esc(e.message)}</div>`}
  };
  $('load-verification').onclick=load;
  await load();
}
function advancedPage(){setHeader('advanced','Advanced input');return `<div class="notice">Load a real sample, upload a compatible CSV/ZIP or dataset folder, select a vehicle, then load its 113 model features into the editable JSON input. You can also enter JSON manually.</div><div class="grid grid-2"><div id="sample-panel"></div><div id="upload-panel"></div></div><div id="uploaded-vehicle-panel"></div><div class="panel"><div class="panel-head"><div><h2>Vehicle JSON input</h2><div class="sub">Expected keys: vehicle_id, time_step, features (105 sensor + 8 specification features).</div></div></div><textarea id="json-input" spellcheck="false" placeholder='{"vehicle_id":"...","time_step":1,"features":{}}'></textarea><div class="row" style="margin-top:10px;flex-wrap:wrap"><button class="btn" id="format-json">Format JSON</button><button class="btn" id="validate-json">Validate JSON</button><button class="btn primary" id="run-json">Run full workflow</button><button class="btn" id="predict-json">Prediction only</button><button class="btn" id="clear-json">Clear</button></div><div id="json-validation" class="small muted" style="margin-top:8px"></div><div id="advanced-result"></div></div>`;}
function renderAdvancedResult(r){const p=r.prediction||{},d=r.recommendation||{},v=r.verification||{},costs=d.expected_costs||{};return panel('Workflow execution result',`Vehicle ${esc(state.advancedPayload?.vehicle_id||r.vehicle_id||'Custom input')} · ${esc(r.final_status||r.status||'Completed')}`,`<div class="grid grid-4">${kpi('Decision class',d.recommended_class??p.predicted_class??'—','Cost-sensitive action','teal')}${kpi('Priority',String(d.priority||'—').toUpperCase(),'Operational priority','amber')}${kpi('P(any failure)',pct(p.calibrated_probability_any_failure??p.probability_any_failure),'Calibrated output where enabled','blue')}${kpi('Verification',esc(v.status||'—'),`${(v.checks||[]).filter(x=>x.passed).length}/${(v.checks||[]).length} checks passed`,'purple')}</div><div class="warning" style="margin-top:12px">${esc(d.safety_notice||'Decision support only. Engineer review required; no maintenance action is executed automatically.')}</div><h3 style="margin:15px 0 8px">Expected cost by decision</h3>${Object.entries(costs).map(([k,val])=>`<div class="cost-row"><b>Class ${esc(k)}</b><div class="bar-track"><div class="bar-fill" style="width:${Math.max(0,Number(val)/(Math.max(1,...Object.values(costs).map(Number)))*100)}%"></div></div><b>${num(val,3)}</b></div>`).join('')||empty('Expected costs were not returned.') }<div class="tabs" style="margin-top:14px"><button class="tab active" data-advanced-tab="summary">Summary</button><button class="tab" data-advanced-tab="agents">Agent reports</button><button class="tab" data-advanced-tab="checks">Verification</button></div><div id="advanced-result-tab">${resultTab('summary',r)}</div><details class="raw-details"><summary>Raw API response</summary><pre class="json-view">${esc(JSON.stringify(r,null,2))}</pre></details>`)}
function setAdvancedJson(payload){
  if(!payload||typeof payload!=='object'||!payload.features||typeof payload.features!=='object'){
    throw new Error('The selected vehicle response did not contain a features object.');
  }
  state.advancedPayload=payload;
  state.advancedJson=JSON.stringify(payload,null,2);
  const editor=$('json-input');
  if(editor)editor.value=state.advancedJson;
  const validation=$('json-validation');
  if(validation)validation.textContent=`Loaded ${Object.keys(payload.features).length} feature values for vehicle ${payload.vehicle_id??'selected vehicle'}.`;
  toast('Vehicle features loaded into JSON editor');
}
async function hydrateAdvanced(){
  try{
    const d=await api('/samples');state.samples=d.samples||[];
    $('sample-panel').innerHTML=panel('Load a real sample','Extracted project sample records',`${state.samples.length?`<div class="field"><label>AVAILABLE SAMPLE</label><select id="sample-select">${state.samples.map(x=>`<option value="${esc(x.id||x.sample_id)}">${esc(x.id||x.sample_id)} · ${esc(x.vehicle_id||'')}</option>`).join('')}</select></div><button class="btn" id="load-sample" style="margin-top:10px">Load sample into JSON editor</button>`:empty('No sample records are currently available. Use dataset upload or manual JSON input.')}`);
  }catch(e){$('sample-panel').innerHTML=panel('Sample loader','',`<div class="error">${esc(e.message)}</div>`)}
  $('upload-panel').innerHTML=panel('Upload SCANIA-compatible dataset','CSV files, ZIP archive, or folder',`<input id="upload-files" type="file" multiple accept=".csv,.zip"><p class="small muted">Select a ZIP containing SCANIA CSV files, or select CSV files individually. Folder selection is supported in Chrome and Edge.</p><input id="upload-folder" type="file" webkitdirectory directory multiple><button class="btn primary" id="upload-btn" style="margin-top:10px">Upload and validate</button><div id="upload-status" class="small muted" style="margin-top:8px"></div>`);
  if(state.advancedJson)$('json-input').value=state.advancedJson;
  if(state.advancedResult)$('advanced-result').innerHTML=renderAdvancedResult(state.advancedResult);
  if($('load-sample'))$('load-sample').onclick=async()=>{try{const d=await api('/samples/'+encodeURIComponent($('sample-select').value));setAdvancedJson({vehicle_id:d.vehicle_id,time_step:d.time_step,features:d.features});}catch(e){toast(e.message)}};
  $('upload-btn').onclick=async()=>{
    const files=[...($('upload-files').files||[]),...($('upload-folder').files||[])];
    if(!files.length){$('upload-status').textContent='Choose a ZIP, CSV files, or a folder first.';return;}
    const fd=new FormData();files.forEach(f=>fd.append('files',f,f.webkitRelativePath||f.name));
    $('upload-btn').disabled=true;$('upload-status').textContent=`Uploading ${files.length} file(s) and checking the model feature schema…`;
    try{
      const d=await api('/uploads',{method:'POST',body:fd});state.advancedDataset=d;
      $('upload-status').textContent=`Dataset ${d.dataset_id} · ${d.compatible?'Compatible with model features':'Compatibility needs attention'} · ${d.available_splits?.join(', ')||d.recommended_split||'No split detected'}`;
      if(!d.compatible){$('uploaded-vehicle-panel').innerHTML=panel('Dataset compatibility','The upload was stored but is not yet model-compatible',`<div class="warning">${esc(d.compatibility?.message||'Required feature columns were not found in the expected files.')}</div>`);return;}
      renderUploadedVehiclePicker(d);
      toast('Dataset uploaded. Select a vehicle to load its features.');
    }catch(e){$('upload-status').textContent=e.message;}
    finally{$('upload-btn').disabled=false;}
  };
  if(state.advancedDataset)renderUploadedVehiclePicker(state.advancedDataset);
  const run=async path=>{
    $('advanced-result').innerHTML='<div class="loading">Running prediction and agent workflow…</div>';
    try{
      const payload=JSON.parse($('json-input').value);
      if(!payload||typeof payload!=='object'||!payload.features||typeof payload.features!=='object')throw new Error('Expected JSON with vehicle_id, time_step and a features object.');
      const d=await api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
      if(d.error)throw new Error(d.error.message||'Workflow returned an error.');
      state.result=d;state.advancedPayload=payload;state.advancedResult=d;state.history.unshift({at:new Date().toLocaleTimeString(),id:payload.vehicle_id||'custom',workflow:path,status:d.final_status||d.status});
      $('advanced-result').innerHTML=renderAdvancedResult(d);
      document.querySelectorAll('[data-advanced-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-advanced-tab]').forEach(x=>x.classList.toggle('active',x===b));$('advanced-result-tab').innerHTML=resultTab(b.dataset.advancedTab,d)});
      toast('Workflow completed');
    }catch(e){$('advanced-result').innerHTML=`<div class="error">${esc(e.message)}</div>`;}
  };
  $('json-input').oninput=e=>{state.advancedJson=e.target.value};
  $('run-json').onclick=()=>run('/workflow/run');$('predict-json').onclick=()=>run('/predict');
  $('clear-json').onclick=()=>{$('json-input').value='';state.advancedJson='';state.advancedPayload=null;state.advancedResult=null;$('advanced-result').innerHTML='';$('json-validation').textContent='';};
  $('format-json').onclick=()=>{try{$('json-input').value=JSON.stringify(JSON.parse($('json-input').value),null,2);state.advancedJson=$('json-input').value;$('json-validation').textContent='JSON formatted successfully.';}catch(e){$('json-validation').textContent='Invalid JSON: '+e.message;}};
  $('validate-json').onclick=()=>{try{const p=JSON.parse($('json-input').value);if(!p||typeof p!=='object'||!p.features||typeof p.features!=='object')throw new Error('Expected an object containing a features object.');$('json-validation').textContent=`Valid JSON · ${Object.keys(p.features).length} feature keys · vehicle ${p.vehicle_id??'not specified'}`;}catch(e){$('json-validation').textContent='Invalid input: '+e.message;}};
}
async function loadUploadedVehicles(){
  if(!state.advancedDataset?.dataset_id)return;
  const split=$('uploaded-split').value;state.advancedSplit=split;
  $('uploaded-vehicle-status').textContent='Reading vehicle IDs from the uploaded operational-readout file…';
  try{
    const d=await api(`/uploads/${encodeURIComponent(state.advancedDataset.dataset_id)}/vehicles?split=${encodeURIComponent(split)}&page=1&page_size=100`);
    state.advancedVehicles=d.items||[];
    $('uploaded-vehicle-status').textContent=`${Number(d.total_vehicles||state.advancedVehicles.length).toLocaleString()} vehicles found · ${d.split||split} split`;
    $('uploaded-vehicle-select').innerHTML=state.advancedVehicles.length?state.advancedVehicles.map(x=>`<option value="${esc(x.vehicle_id)}">${esc(x.vehicle_id)}</option>`).join(''):'<option value="">No vehicles found</option>';
    $('load-uploaded-vehicle').disabled=!state.advancedVehicles.length;
  }catch(e){$('uploaded-vehicle-status').textContent=e.message;}
}
function renderUploadedVehiclePicker(d){
  const splits=d.available_splits||[d.recommended_split||'validation'];
  $('uploaded-vehicle-panel').innerHTML=panel('Select a vehicle from uploaded dataset',`Dataset ${esc(d.dataset_id)} · ${d.compatible?'Model features compatible':'Compatibility check required'}`,`<div class="toolbar"><div class="field"><label>DATA SPLIT</label><select id="uploaded-split">${splits.map(x=>`<option value="${esc(x)}" ${x===(d.recommended_split||splits[0])?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>VEHICLE ID</label><select id="uploaded-vehicle-select"><option value="">Load vehicles first</option></select></div><button class="btn" id="load-uploaded-vehicles">Load vehicle list</button><button class="btn primary" id="load-uploaded-vehicle" disabled>Load features into JSON</button></div><div id="uploaded-vehicle-status" class="small muted">Choose a split and load its vehicle IDs.</div>`);
  $('load-uploaded-vehicles').onclick=loadUploadedVehicles;
  $('uploaded-split').onchange=loadUploadedVehicles;
  $('load-uploaded-vehicle').onclick=async()=>{
    const id=$('uploaded-vehicle-select').value;if(!id)return;
    $('uploaded-vehicle-status').textContent=`Loading latest operational record and specification features for ${id}…`;
    try{const d=await api(`/uploads/${encodeURIComponent(state.advancedDataset.dataset_id)}/vehicles/${encodeURIComponent(id)}?split=${encodeURIComponent($('uploaded-split').value)}`);setAdvancedJson(d.payload);$('uploaded-vehicle-status').textContent=`Loaded ${id} · ${d.operational_records_for_vehicle} operational records considered · ${Object.keys(d.payload.features||{}).length} features.`;}
    catch(e){$('uploaded-vehicle-status').textContent=e.message;}
  };
  loadUploadedVehicles();
}

const pages={overview:overviewPage,analysis:analysisPage,agents:agentsPage,decisions:decisionsPage,analytics:analyticsPage,verification:verificationPage,advanced:advancedPage};
async function render(){if(location.hash==='#analysis')state.analysisScroll=window.scrollY;if(location.hash==='#advanced'&&$('json-input'))state.advancedJson=$('json-input').value;const id=(location.hash||'#overview').slice(1),page=pages[id]?id:'overview';$('view').innerHTML=pages[page]();try{if(page==='overview')await hydrateOverview();if(page==='analysis')await hydrateAnalysis();if(page==='analytics')await hydrateAnalytics();if(page==='verification')await hydrateVerification();if(page==='advanced')await hydrateAdvanced();}catch(e){$('view').insertAdjacentHTML('beforeend',`<div class="error">${esc(e.message)}</div>`)}}
$('refresh-btn').onclick=async()=>{await refreshBase();await render();toast('Platform data refreshed')};window.addEventListener('scroll',()=>{if(location.hash==='#analysis')state.analysisScroll=window.scrollY},{passive:true});window.addEventListener('hashchange',render);window.addEventListener('resize',()=>{if(location.hash==='#overview')hydrateOverview().catch(()=>{})});
(async()=>{await refreshBase();await render()})();